#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    size_t len = strlen(input);
    if (len > 1023) { // original limit
        puts("USAGE");
        return 0;
    }
    if (strcmp(mode, "escape") == 0) {
        char *out = malloc(len * 2 + 1); // worst case every char escaped
        if (!out) return 1;
        size_t out_idx = 0;
        for (size_t i = 0; i < len; ++i) {
            unsigned char c = (unsigned char)input[i];
            switch (c) {
                case '\\':
                    out[out_idx++] = '\\';
                    out[out_idx++] = '\\';
                    break;
                case '"':
                    out[out_idx++] = '\\';
                    out[out_idx++] = '"';
                    break;
                case '\n':
                    out[out_idx++] = '\\';
                    out[out_idx++] = 'n';
                    break;
                case '\t':
                    out[out_idx++] = '\\';
                    out[out_idx++] = 't';
                    break;
                default:
                    out[out_idx++] = c;
                    break;
            }
        }
        out[out_idx] = '\0';
        puts(out);
        free(out);
        return 0;
    } else if (strcmp(mode, "unescape") == 0) {
        char *out = malloc(len + 1);
        if (!out) return 1;
        size_t out_idx = 0;
        for (size_t i = 0; i < len; ) {
            if (input[i] == '\\') {
                if (i + 1 >= len) {
                    puts("INVALID");
                    free(out);
                    return 0;
                }
                char nxt = input[i + 1];
                switch (nxt) {
                    case '\\': out[out_idx++] = '\\'; break;
                    case '"': out[out_idx++] = '"'; break;
                    case 'n': out[out_idx++] = '\n'; break;
                    case 't': out[out_idx++] = '\t'; break;
                    default:
                        puts("INVALID");
                        free(out);
                        return 0;
                }
                i += 2;
            } else {
                out[out_idx++] = input[i++];
            }
        }
        out[out_idx] = '\0';
        puts(out);
        free(out);
        return 0;
    } else {
        puts("INVALID_MODE");
        return 0;
    }
}
